const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Point([-95.3698, 29.7604]).buffer(25000).bounds(); // Houston core ~25 km
    const scale = 1000; // per best practice to avoid timeouts
    const aprilStart = '2024-04-01';
    const aprilEnd = '2024-05-01';
    const may18Start = '2024-05-18';
    const may18End = '2024-05-19';

    // 2. Data Acquisition & Check (Black Marble Daily - VNP46A2)
    const dailyId = 'NOAA/VIIRS/001/VNP46A2';
    let aprilCol = ee.ImageCollection(dailyId).filterDate(aprilStart, aprilEnd).filterBounds(region);
    let may18Col = ee.ImageCollection(dailyId).filterDate(may18Start, may18End).filterBounds(region);

    let aprilSize, may18Size;
    try {
      aprilSize = await aprilCol.size().getInfo();
      may18Size = await may18Col.size().getInfo();
    } catch (e) {
      console.log('Dataset access error (VNP46A2).');
      console.log('D');
      return;
    }

    if (aprilSize === 0 || may18Size === 0) {
      console.log(`April Images: ${aprilSize}`);
      console.log(`May 18 Images: ${may18Size}`);
      console.log('C1');
      return;
    }

    // Determine usable band
    let bands = await ee.Image(aprilCol.first()).bandNames().getInfo();
    if (!bands || bands.length === 0) {
      console.log('Band discovery failed.');
      console.log('D');
      return;
    }
    const preferredBands = [
      'DNB_BRDF-Corrected_NTL',
      'Gap_Filled_DNB_BRDF-Corrected_NTL',
      'RadE9_Mult_Nadir_Norm',
      'CorrectedNTL',
      'avg_rad'
    ];
    let bandName = preferredBands.find(b => bands.indexOf(b) !== -1);
    if (!bandName) {
      // Fallback to first band if none of the preferred found
      bandName = bands[0];
    }

    // 3. Processing: composites
    const aprilImg = aprilCol.select([bandName]).mean();
    const may18Img = may18Col.select([bandName]).mean();

    // Helper to get stats
    async function stats(img, band, label) {
      const countDict = await img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).getInfo();
      const meanDict = await img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).getInfo();
      const totalDict = await ee.Image(1).rename('ones').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).getInfo();
      const count = countDict ? countDict[band] : null;
      const mean = meanDict ? meanDict[band] : null;
      const total = totalDict ? totalDict['ones'] : null;
      return { label, count, mean, total };
    }

    const aprilStats = await stats(aprilImg, bandName, 'April');
    const may18Stats = await stats(may18Img, bandName, '2024-05-18');

    // 4. Validation & Printing concise evidence
    // Check for No Valid Pixels
    if (!aprilStats.total || !may18Stats.total || aprilStats.total === 0 || may18Stats.total === 0) {
      console.log(`Dataset: ${dailyId}, band=${bandName}, scale=${scale}m`);
      console.log('No valid grid pixels (total==0).');
      console.log('C2');
      return;
    }
    const aprilValid = (aprilStats.count || 0);
    const may18Valid = (may18Stats.count || 0);
    if (aprilValid === 0 || may18Valid === 0) {
      console.log(`Dataset: ${dailyId}, band=${bandName}, scale=${scale}m`);
      console.log(`April Images: ${aprilSize}, Valid Pixels After Mask: ${aprilValid}/${aprilStats.total}`);
      console.log(`May 18 Images: ${may18Size}, Valid Pixels After Mask: ${may18Valid}/${may18Stats.total}`);
      console.log('C2');
      return;
    }

    const aprilMean = aprilStats.mean;
    const may18Mean = may18Stats.mean;

    // Calculation failure (null/NaN)
    const invalid =
      aprilMean === null || may18Mean === null ||
      !isFinite(aprilMean) || !isFinite(may18Mean);
    if (invalid) {
      console.log(`Dataset: ${dailyId}, band=${bandName}, scale=${scale}m`);
      console.log(`April Images: ${aprilSize}`);
      console.log(`May 18 Images: ${may18Size}`);
      console.log('C3');
      return;
    }

    const aprilValidPct = (aprilValid / aprilStats.total) * 100.0;
    const may18ValidPct = (may18Valid / may18Stats.total) * 100.0;
    const delta = may18Mean - aprilMean;
    const pct = (aprilMean !== 0) ? (delta / aprilMean) * 100.0 : null;

    console.log(`Dataset: ${dailyId}, band=${bandName}, scale=${scale}m`);
    console.log(`April imgs: ${aprilSize}, mean: ${aprilMean.toFixed(3)}, valid px: ${aprilValid}/${aprilStats.total} (${aprilValidPct.toFixed(1)}%)`);
    console.log(`2024-05-18 imgs: ${may18Size}, mean: ${may18Mean.toFixed(3)}, valid px: ${may18Valid}/${may18Stats.total} (${may18ValidPct.toFixed(1)}%)`);
    console.log(`Change: Δ=${delta.toFixed(3)}${pct !== null ? `, pct=${pct.toFixed(1)}%` : ''}`);

    // 5. Final Answer
    // A: Yes (decreased) if May18 < AprilAvg; else B: No
    if (may18Mean < aprilMean) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
